function cycle_terminal(array $state):bool {
    if(($state['schema']??null)!==1||!array_key_exists('pending',$state)||$state['pending']!==null||!is_array($state['completed']??null))return false;
    if(!array_key_exists('nightly_cycle',$state))return true;
    $c=$state['nightly_cycle'];if(!is_array($c))return false;
    if(($c['state']??null)==='interrupted_reconciled')return monitor_hook_reconciled_cycle_valid($c)||monitor_hook_expired_reconciled_cycle_valid($c)||monitor_hook_price27316_cycle_valid($c)||monitor_hook_price81173_cycle_valid($c);
    if(monitor_hook_preflight_cycle_valid($c))return true;
    if(!in_array($c['state']??null,['completed','budget_exhausted'],true))return false;
    if(!is_string($c['collector_run_id']??null)||preg_match('/\A[1-9][0-9]{0,19}\z/D',$c['collector_run_id'])!==1
        ||!is_string($c['night_date']??null)||preg_match('/\A[0-9]{4}-[0-9]{2}-[0-9]{2}\z/D',$c['night_date'])!==1
        ||($c['budget_seconds']??null)!==1800||($c['finish_reserve_seconds']??null)!==300)return false;
    foreach(['collection_started_at','started_at','finished_at'] as $k)if(monitor_hook_preflight_utc_time($c[$k]??null)===null)return false;
    if($c['started_at']>$c['finished_at'])return false;
    foreach(['duration_seconds','updated_pairs','unchanged_pairs','eligible_pairs','held_pairs','scanned_pairs','remaining_unscanned_pairs'] as $k)if(!is_int($c[$k]??null)||$c[$k]<0)return false;
    return true;
}
