function readfile_exact(string $path,int $limit):array{
    clearstatcache(true,$path);must(!is_link($path)&&is_file($path)&&realpath($path)===$path,'path_invalid');
    $f=fopen($path,'rb');must(is_resource($f),'file_open_failed');
    try{
        $before=fstat($f);must(is_array($before)&&$before['size']>0&&$before['size']<=$limit,'file_size_invalid');
        $raw=stream_get_contents($f,$limit+1);must(is_string($raw)&&strlen($raw)===$before['size'],'file_read_changed');clearstatcache(true,$path);$after=lstat($path);
        foreach(['ino','dev','size','mtime','ctime'] as $k)must(($after[$k]??null)===$before[$k],'file_changed');
        return [$raw,$before];
    }finally{fclose($f);}
}
function write_new(string $path,string $raw,int $mode=0600):void{
    $f=fopen($path,'xb');must(is_resource($f),'exclusive_create_failed');
    try{must(chmod($path,$mode),'chmod_failed');$n=0;while($n<strlen($raw)){$written=fwrite($f,substr($raw,$n));must(is_int($written)&&$written>0,'file_write_failed');$n+=$written;}must(fflush($f),'flush_failed');if(function_exists('fsync'))must(fsync($f),'sync_failed');}
    finally{fclose($f);}
}
function journal_line($f,string $path):array {
    $stat=fstat($f);must(is_array($stat)&&$stat['size']>0&&$stat['size']<=1073741824,'journal_size_invalid');
    // The accepted reader validates every historical cycle and hashes the original
    // prefix under the same lock. No journal bytes are rewritten or appended.
    $history=monitor_hook_read_history($f);
    must($history['trailing_blank_lines']===0&&$history['pin']['bytes']===$stat['size'],'journal_incomplete');
    $state=$history['state'];must(is_array($state)&&array_key_exists('pending',$state),'journal_invalid');
    clearstatcache(true,$path);$named=lstat($path);$after=fstat($f);
    foreach(['ino','dev','size','mtime','ctime'] as $k)must(($named[$k]??null)===$stat[$k]&&($after[$k]??null)===$stat[$k],'journal_changed');
    return ['pin'=>$history['pin'],'identity'=>array_intersect_key($stat,array_flip(['ino','dev','size','mtime','ctime'])),
        'pending_null'=>$state['pending']===null,'cycle_terminal'=>cycle_terminal($state),
        'cycle_state'=>$state['nightly_cycle']['state']??null,'cycle_run_id'=>$state['nightly_cycle']['collector_run_id']??null];
}
